20	class SortOneCore
21	{
22	public:
23	    __aicore__ inline SortOneCore() {};
24	    __aicore__ inline void Init(
25	        GM_ADDR keys, GM_ADDR values, GM_ADDR sortedKeys, GM_ADDR sortedValues,
26	        const SortKernelTiling* tiling, TPipe* tPipe);
27	    __aicore__ inline void Process();
28	
