30	    __aicore__ inline void CopyIn();
31	    __aicore__ inline void SortCompute();
32	    __aicore__ inline void CopyOut();
33	
34	protected:
35	    TPipe* pipe;
36	    TQue<QuePosition::VECIN, 1> copyInQueue;
37	    TQue<QuePosition::VECOUT, 1> copyOutQueue;
38	    TBuf<TPosition::VECCALC> tempBuffer;
39	    TBuf<TPosition::VECCALC> sortedBuffer;
40	
41	    GlobalTensor<int32_t> keysGm;
42	    GlobalTensor<int32_t> valuesGm;
43	    GlobalTensor<int32_t> sortedKeysGm;
44	    GlobalTensor<int32_t> sortedValuesGm;
45	
46	    int64_t totalLength;
47	    int64_t sortNum;
48	    int64_t tileLength;
49	    int64_t coreNum;
50	};
51	
52	__aicore__ inline void SortOneCore::Init(
53	    GM_ADDR keys, GM_ADDR values, GM_ADDR sortedKeys, GM_ADDR sortedValues,
54	    const SortKernelTiling* tiling, TPipe* tPipe)
55	{
56	    this->pipe = tPipe;
57	    this->totalLength = tiling->totalLength;
58	    this->tileLength = AlignUp(this->totalLength, sizeof(int32_t));
59	    this->sortNum = CeilDiv(this->tileLength, ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
60	    this->coreNum = tiling->coreNum;
61	
62	    keysGm.SetGlobalBuffer((__gm__ int32_t*)keys, this->tileLength);
63	    valuesGm.SetGlobalBuffer((__gm__ int32_t*)values, this->tileLength);
64	    sortedKeysGm.SetGlobalBuffer((__gm__ int32_t*)sortedKeys, this->tileLength);
65	    sortedValuesGm.SetGlobalBuffer((__gm__ int32_t*)sortedValues, this->tileLength);
66	
67	    int64_t kvFactor = 2;
68	    int64_t buffSize = this->sortNum * sizeof(int32_t) * kvFactor;
69	    pipe->InitBuffer(copyInQueue, 1, buffSize);
70	    pipe->InitBuffer(copyOutQueue, 1, buffSize);
71	    pipe->InitBuffer(tempBuffer, buffSize);
72	    pipe->InitBuffer(sortedBuffer, buffSize);
73	}
74	
75	__aicore__ inline void SortOneCore::CopyIn()
76	{
77	    LocalTensor<int32_t> inLocal = copyInQueue.AllocTensor<int32_t>();
78	    DataCopyExtParams dataCopyParams{
79	        static_cast<uint16_t>(1), static_cast<uint32_t>(this->totalLength * sizeof(int32_t)), 0, 0, 0};
80	    DataCopyPadExtParams dataCopyPadParams{false, 0, 0, 0};
81	    DataCopyPad(inLocal[0], keysGm, dataCopyParams, dataCopyPadParams);
82	    DataCopyPad(inLocal[this->sortNum], valuesGm, dataCopyParams, dataCopyPadParams);
83	    copyInQueue.EnQue(inLocal);
84	}
85	
86	__aicore__ inline void SortOneCore::SortCompute()
87	{
88	    LocalTensor<int32_t> inLocal = copyInQueue.DeQue<int32_t>();
89	    LocalTensor<int32_t> keysLocal = inLocal[0];
90	    LocalTensor<float> keysFp32 = keysLocal.ReinterpretCast<float>();
91	    Cast(keysFp32, keysLocal, RoundMode::CAST_ROUND, this->tileLength);
92	    Muls(keysFp32, keysFp32, (float)-1, this->tileLength);
93	
94	    int64_t duplicateNum = this->totalLength % ONE_REPEAT_SORT_NUM;
95	    if (duplicateNum > 0) {
96	        int duplicateIndex = this->totalLength - duplicateNum;
97	        uint64_t mask0 = UINT64_MAX;
98	        mask0 = mask0 << duplicateNum;
99	        mask0 = mask0 & (UINT64_MAX >> ONE_REPEAT_SORT_NUM);
100	        uint64_t mask[2] = {mask0, 0};
101	        Duplicate(keysFp32[duplicateIndex], MIN_FP32, mask, 1, DST_BLK_STRIDE, DST_REP_STRIDE);
102	    }
103	
104	    LocalTensor<float> concatLocal;
105	    LocalTensor<float> tempTensor = tempBuffer.Get<float>(GetSortLen<float>(this->sortNum));
106	    Concat(concatLocal, keysFp32, tempTensor, this->sortNum / ONE_REPEAT_SORT_NUM);
107	
108	    LocalTensor<float> sortedLocal = sortedBuffer.Get<float>(GetSortLen<float>(this->sortNum));
109	    LocalTensor<uint32_t> valuesLocal = inLocal[this->sortNum].ReinterpretCast<uint32_t>();
110	    Sort<float, true>(sortedLocal, concatLocal, valuesLocal, tempTensor, this->sortNum / ONE_REPEAT_SORT_NUM);
111	
112	    LocalTensor<float> outLocal = copyOutQueue.AllocTensor<float>();
113	    LocalTensor<float> sortedKeysFp32 = outLocal[0];
114	    LocalTensor<uint32_t> sortedValuesU32 = outLocal[this->sortNum].ReinterpretCast<uint32_t>();
115	    Extract(sortedKeysFp32, sortedValuesU32, sortedLocal, this->sortNum / ONE_REPEAT_SORT_NUM);
116	    Muls(sortedKeysFp32, sortedKeysFp32, (float)-1, this->tileLength);
117	
118	    LocalTensor<int32_t> sortedKeysInt32 = sortedKeysFp32.ReinterpretCast<int32_t>();
119	    Cast(sortedKeysInt32, sortedKeysFp32, RoundMode::CAST_ROUND, this->tileLength);
120	
121	    copyOutQueue.EnQue<float>(outLocal);
122	    copyInQueue.FreeTensor(inLocal);
123	}
124	
125	__aicore__ inline void SortOneCore::CopyOut()
126	{
127	    LocalTensor<int32_t> outLocal = copyOutQueue.DeQue<int32_t>();
128	    DataCopyParams intriParams;
129	    intriParams.blockCount = 1;
130	    intriParams.blockLen = this->totalLength * sizeof(int32_t);
131	    DataCopyPad(sortedKeysGm, outLocal[0], intriParams);
132	    DataCopyPad(sortedValuesGm, outLocal[this->sortNum], intriParams);
133	    copyOutQueue.FreeTensor(outLocal);
134	}
135	
136	__aicore__ inline void SortOneCore::Process()
137	{
138	    if (GetBlockIdx() == 0) {
139	        CopyIn();
140	        SortCompute();
141	        CopyOut();
142	    }
143	    if (coreNum > 1) {
144	        AscendC::SyncAll();
145	    }
146	}
