#include <algorithm>
#include <cstring>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_npu_moe_gating_top_k_softmax.h"

namespace ascend_kernel {

constexpr int64_t ONE_REPEAT_SORT_NUM = 32;
constexpr int64_t BLOCK_BYTES = 32;

struct MoEGatingTopKSoftmaxTiling {
    int64_t B;
    int64_t E;
    int64_t k;
    int64_t E_align;
    int64_t rows_per_core;
    int64_t core_num;
    int64_t dtype_size;
};

static int64_t AlignUpDiv(int64_t x, int64_t div)
{
    return (x + div - 1) / div * div;
}

static int64_t AlignUpBytes(int64_t elements, int64_t elemSize)
{
    return (elements * elemSize + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES;
}

std::tuple<at::Tensor, at::Tensor, at::Tensor> npu_moe_gating_top_k_softmax(
    const at::Tensor& x, const c10::optional<at::Tensor>& finished_opt, int64_t k)
{
    // ================================================================
    // Input validation
    // ================================================================
    TORCH_CHECK(x.dim() >= 2, "x must be >= 2D");
    int64_t E = x.size(-1);
    TORCH_CHECK(k > 0 && k <= E, "k must be in (0, ", E, "], got ", k);
    TORCH_CHECK(k <= 1024, "k must be <= 1024");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    auto dtype = x.scalar_type();
    TORCH_CHECK(dtype == at::kHalf || dtype == at::kBFloat16 || dtype == at::kFloat,
        "Unsupported dtype, expected float16/bfloat16/float32");

    int64_t dtypeSize = dtype == at::kHalf ? 2 : (dtype == at::kBFloat16 ? 2 : 4);

    // Compute B (flattened batch)
    int64_t B = 1;
    for (int64_t d = 0; d < x.dim() - 1; ++d) {
        B *= x.size(d);
    }

    // Handle finished tensor
    at::Tensor finished;
    if (finished_opt.has_value()) {
        finished = finished_opt.value().to(at::kBool).contiguous();
        TORCH_CHECK(finished.numel() == B, "finished numel must match batch size");
    } else {
        finished = at::zeros({B}, at::TensorOptions().dtype(at::kBool).device(at::kPrivateUse1));
    }

    // ================================================================
    // Platform query
    // ================================================================
    auto* ascendcPlatform = platform_ascendc::PlatformAscendCMgr::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    if (coreNum <= 0) {
        coreNum = 1;
    }
    // Cap cores to the number of rows
    int64_t actualCores = std::min(coreNum, B);
    if (actualCores < 1) actualCores = 1;

    // ================================================================
    // Tiling computation
    // ================================================================
    int64_t E_align = AlignUpDiv(E, ONE_REPEAT_SORT_NUM);
    int64_t rowsPerCore = (B + actualCores - 1) / actualCores;

    // Pack tiling to CPU tensor, then move to NPU
    MoEGatingTopKSoftmaxTiling tilingHost{};
    tilingHost.B = B;
    tilingHost.E = E;
    tilingHost.k = k;
    tilingHost.E_align = E_align;
    tilingHost.rows_per_core = rowsPerCore;
    tilingHost.core_num = actualCores;
    tilingHost.dtype_size = dtypeSize;

    at::Tensor tilingCpu = at::empty(
        {static_cast<int64_t>(sizeof(MoEGatingTopKSoftmaxTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    std::memcpy(tilingCpu.data_ptr(), &tilingHost, sizeof(MoEGatingTopKSoftmaxTiling));
    at::Tensor tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // ================================================================
    // Allocate output tensors
    // ================================================================
    at::Tensor topkValues = at::empty({B, k}, x.options());
    at::Tensor topkIndices = at::empty({B, k},
        at::TensorOptions().dtype(at::kInt).device(at::kPrivateUse1));
    at::Tensor rowIdx = at::empty({B, k},
        at::TensorOptions().dtype(at::kInt).device(at::kPrivateUse1));

    // ================================================================
    // Kernel launch
    // ================================================================
    uint32_t blockDim = static_cast<uint32_t>(actualCores);
    EXEC_KERNEL_CMD(npu_moe_gating_top_k_softmax, blockDim,
        x, finished, topkValues, topkIndices, rowIdx, tilingNpu);

    return std::make_tuple(topkValues, topkIndices, rowIdx);
}

}  // namespace ascend_kernel
