cases = []
with open(json_path) as f:
    for line in f:
        line = line.strip()
        if line:
            cases.append(json.loads(line))

print(f'Running full validation: {len(cases)} cases')
failed = []
all_pass = True

for i, case in enumerate(cases):
    inputs_info = case['inputs']
    args = {}
    for inp in inputs_info:
        if inp['type'] == 'tensor':
            shape = inp['shape']
            dtype_str = inp['dtype']
            if dtype_str == 'bool':
                args[inp['name']] = torch.rand(shape, device='npu:0') > 0.5
            elif dtype_str == 'float16':
                args[inp['name']] = torch.randn(shape, dtype=torch.float16, device='npu:0')
            elif dtype_str == 'float32':
                args[inp['name']] = torch.randn(shape, dtype=torch.float32, device='npu:0')
            elif dtype_str == 'bfloat16':
                args[inp['name']] = torch.randn(shape, dtype=torch.bfloat16, device='npu:0')
        elif inp['type'] == 'attr':
            args[inp['name']] = inp['value']

    x = args.get('x')
    finished = args.get('finished', None)
    k = args.get('k', 1)

    try:
        # Reference
        ref_result = torch_npu.npu_moe_gating_top_k_softmax(x, finished=finished, k=k)

        # Our kernel
        our_result = torch.ops.npu.npu_moe_gating_top_k_softmax(x, finished, k)

        case_fail = False
        for j, (ref, our) in enumerate(zip(ref_result, our_result)):
            if ref.shape != our.shape:
                case_fail = True
                failed.append(f'Case {i}: shape={list(x.shape)}, dtype={x.dtype}, k={k}, output {j} shape mismatch')
                break
            max_diff = (ref.float() - our.float()).abs().max().item()
            if max_diff > 0.01:
                case_fail = True
                failed.append(f'Case {i}: shape={list(x.shape)}, dtype={x.dtype}, k={k}, output {j} max_diff={max_diff:.6f}')
                break

        if case_fail:
            all_pass = False
    except Exception as e:
        all_pass = False
        failed.append(f'Case {i}: shape={list(x.shape)}, dtype={x.dtype}, k={k}, ERROR: {e}')

passed = len(cases) - len(failed)
print(f'Result: {passed}/{len(cases)} passed')
if failed:
    for f in failed:
        print(f'  FAIL: {f}')
    print('FULL VALIDATION: FAIL')
else:
